using System;
using System.IO;
using System.Linq;
using System.Text;
using UnityEngine;
using DragLab.Data;
using DragLab.Domain;
using DragLab.Domain.Mechanics;
using DragLab.Infrastructure;
namespace DragLab.Editor {
 public static class VehicleMarketVerification {
 public static void RunStandalone(){
 int checks=0;var log=new StringBuilder();Action<bool,string> check=(ok,label)=>{if(!ok)throw new InvalidOperationException(label);checks++;log.AppendLine("PASS "+label);};var cat=MechanicsTransactions.Catalog();long now=DateTime.UtcNow.Ticks;
 Func<PlayerProfile> fresh=()=>{var p=PlayerProfile.NewGame(now);VehicleListings.Initialize(p,cat,12345);MechanicsOwnership.Ensure(p,cat);return p;};
 var initial=fresh();check(initial.cars.Count==0&&initial.SelectedCar==null&&initial.firstPurchasePending,"fresh game starts without gifted hardware/car");check(initial.vehicleStock.listings.Count==3&&initial.vehicleStock.listings.All(o=>o.used&&o.reputation==0),"three fixed used starters, no reputation restriction");
 var second=fresh();check(JsonUtility.ToJson(initial.vehicleStock)==JsonUtility.ToJson(second.vehicleStock),"fixed opening selection repeats exactly");
 foreach(var offer in initial.vehicleStock.listings){var p=fresh();var actual=VehicleListings.Find(p,offer.listingId);int cost=PaidEconomy.DealerPrice(cat,VehicleListings.Costs,VehicleListings.Values,actual);log.AppendLine("STARTER "+offer.model+" price="+cost+" reserve="+(p.cash-cost));check(p.cash>=cost+300,offer.model+" budget leaves maintenance reserve");var before=actual.parts.Select(x=>JsonUtility.ToJson(x.condition)).ToArray();var ids=actual.parts.Select(x=>x.instanceId).ToArray();var quote=PaidEconomy.Quote(p,cat,VehicleListings.Costs,VehicleListings.Values,new PaymentRequest{kind=PaymentKind.Car,offer=actual},now);int money=p.cash;PlayerProfile committed;string error;if(!MechanicsTransactions.Try(p,cat,p.revision,q=>PaidEconomy.Pay(q,cat,VehicleListings.Costs,VehicleListings.Values,quote,now,VehicleListings.Find(q,actual.listingId)),q=>true,out committed,out error))throw new InvalidOperationException(error);p=committed;var car=p.SelectedCar;check(p.cash==money-cost&&p.cars.Count==1&&!p.firstPurchasePending,offer.model+" exact paid starter selects owned car");check(ids.SequenceEqual(p.parts.Select(x=>x.instanceId))&&actual.parts.Zip(p.parts,(a,b)=>SnapshotEquality.Serialized(JsonUtility.ToJson(a.condition),b.condition)).All(x=>x),offer.model+" seller component identities/condition retained exactly");check(car.fuel.litres==actual.fuel.litres&&car.fluids.oilCondition==actual.fluids.oilCondition&&car.mileageKm==actual.mileageKm,offer.model+" retained fuel/fluids/mileage");check(MechanicsOwnership.Validate(p,cat)==null&&p.vehicleStock.listings.Count==20,offer.model+" normal new/used market unlocked: "+MechanicsOwnership.Validate(p,cat)+" stock "+p.vehicleStock.listings.Count);
 var copy=JsonUtility.FromJson<PlayerProfile>(JsonUtility.ToJson(p));MechanicsOwnership.Ensure(copy,cat);check(SnapshotEquality.Profile(JsonUtility.ToJson(p),copy,cat),offer.model+" save/reload retains listings and ownership");string stock=JsonUtility.ToJson(p.vehicleStock);MechanicsOwnership.Ensure(p,cat);check(stock==JsonUtility.ToJson(p.vehicleStock),offer.model+" normalization never rerolls listings");
 var build=MechanicsOwnership.Resolve(p,car,cat);var simulation=new CarSimulation(build.spec,build.tune,new DriverSettings{wearMode=WearMode.Full},p.parts);simulation.SetFluids(car.fluids);simulation.Launch(0);for(int i=0;i<4000&&simulation.state.distance<402.336;i++)simulation.Step(DragMath.FixedStep,new DriverInput{throttle=1});check(simulation.state.distance>=402.336&&!simulation.state.engineFailed&&simulation.mechanics.parts.All(x=>!x.condition.failed),offer.model+" worn starter survives a proper factory pass");
 }
 var owned=fresh();var selected=owned.vehicleStock.listings[0];VehicleCollection.Buy(owned,cat,selected);var clone=JsonUtility.FromJson<PlayerProfile>(JsonUtility.ToJson(owned));MechanicsOwnership.Ensure(clone,cat);string current=JsonUtility.ToJson(owned.vehicleStock);VehicleListings.AfterRace(owned,cat);VehicleListings.AfterRace(owned,cat);check(current!=JsonUtility.ToJson(owned.vehicleStock)&&owned.vehicleStock.generation==1,"two runs advance refresh counter without swapping stock");string held=string.Join("|",owned.vehicleStock.listings.Select(JsonUtility.ToJson));VehicleListings.AfterRace(owned,cat);check(held!=string.Join("|",owned.vehicleStock.listings.Select(JsonUtility.ToJson))&&owned.vehicleStock.generation==2,"third completed paid/free run refreshes stock");for(int i=0;i<3;i++)VehicleListings.AfterRace(clone,cat);check(JsonUtility.ToJson(owned.vehicleStock)==JsonUtility.ToJson(clone.vehicleStock),"same persisted seed and run count reproduce refresh exactly");
 check(owned.vehicleStock.listings.Count(o=>o.used)==7&&owned.vehicleStock.listings.Count(o=>!o.used)==13,"normal market contains new and used variants");check(owned.vehicleStock.listings.Where(o=>!o.used).SelectMany(o=>o.parts).All(p=>p.condition.health==1&&!p.condition.failed),"new stock always has unused healthy components");
 check(owned.vehicleStock.listings.Where(o=>o.used).SelectMany(o=>o.parts).Select(o=>o.condition.health).Distinct().Count()>3,"used cars have individually varied part condition");
 var used=owned.vehicleStock.listings.First(o=>o.used);owned.cash=100000;owned.reputation=1000;var stale=PaidEconomy.Quote(owned,cat,VehicleListings.Costs,VehicleListings.Values,new PaymentRequest{kind=PaymentKind.Car,offer=used},now);string original=JsonUtility.ToJson(owned);used.price++;bool denied=false;try{PaidEconomy.Pay(owned,cat,VehicleListings.Costs,VehicleListings.Values,stale,now,used);}catch(InvalidOperationException){denied=true;}check(denied,"changed listing cannot authorize an old payment");used.price--;check(original==JsonUtility.ToJson(owned),"rejected purchase changes no assets/cash");VehicleCollection.Buy(owned,cat,used);check(VehicleListings.Find(owned,used.listingId)==null,"used listing consumed once");denied=false;try{VehicleCollection.Buy(owned,cat,used);}catch(InvalidOperationException){denied=true;}check(denied,"sold listing cannot duplicate its components");
 var next=owned.RestartKeepingPreferences(now);MechanicsOwnership.Ensure(next,cat);check(next.cars.Count==0&&next.firstPurchasePending&&next.parts.Count==0&&next.vehicleStock.listings.Count==3,"reset returns to fixed starter selection while clearing progression");check(JsonUtility.ToJson(next.driving)==JsonUtility.ToJson(owned.driving),"reset preserves driving preferences");
 var folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../reports/variety"));Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"market-verification.txt"),log+"TOTAL "+checks,new UTF8Encoding(false));Debug.Log("Vehicle market checks: "+checks);
 }
 }
}
